const tabId = 730410078;
const controls = await browserjs(tabId, () => {
  const container = document.querySelector('div.desktop-view.row');

  // Find Obedience
  const obedienceLabels = Array.from(container.querySelectorAll('label, span, div')).filter(el => el.textContent && el.textContent.includes('Obedience'));

  // Find State controls
  const stateInputs = Array.from(container.querySelectorAll('input, select, .typeahead-input, svg path, svg text'));

  // Find Date inputs
  const dateInputs = Array.from(container.querySelectorAll('input[placeholder*="MM/DD/YYYY" i], input.date-start, input.date-end'));

  // Find buttons
  const buttons = Array.from(container.querySelectorAll('button'));

  return {
    obedienceCount: obedienceLabels.length,
    obedienceHTML: obedienceLabels[0] ? obedienceLabels[0].outerHTML.slice(0, 300) : null,
    dateInputs: dateInputs.map(d => ({ className: d.className, value: d.value, placeholder: d.placeholder })),
    buttons: buttons.map(b => ({ text: b.innerText.trim(), className: b.className }))
  };
});
console.log(JSON.stringify(controls, null, 2));

