const tabId = 730410078;
const details = await browserjs(tabId, () => {
  const container = document.querySelector('div.desktop-view.row');

  // Find all elements that have text "Obedience"
  const obedienceEl = Array.from(container.querySelectorAll('*')).find(el => el.children.length === 0 && el.textContent.includes('Obedience'));

  // Find all checkboxes
  const checkboxes = Array.from(container.querySelectorAll('input[type="checkbox"]')).map(c => ({
    id: c.id,
    checked: c.checked,
    parentText: c.parentElement ? c.parentElement.textContent.trim() : '',
    label: c.closest('label') ? c.closest('label').textContent.trim() : ''
  }));

  // Find Retrieve Events button
  const retrieveBtn = Array.from(document.querySelectorAll('*')).find(el => el.children.length === 0 && el.textContent.includes('RETRIEVE EVENTS'));

  // Find State search input
  const stateInput = container.querySelector('input[placeholder*="Search state by name"]');

  return {
    obedienceText: obedienceEl ? obedienceEl.outerHTML : null,
    obedienceParent: obedienceEl ? obedienceEl.parentElement.outerHTML : null,
    checkboxes,
    retrieveBtn: retrieveBtn ? {
      tag: retrieveBtn.tagName,
      parentTag: retrieveBtn.parentElement.tagName,
      parentHTML: retrieveBtn.parentElement.outerHTML.slice(0, 200)
    } : null,
    stateInput: stateInput ? stateInput.outerHTML : null
  };
});
console.log(JSON.stringify(details, null, 2));

