const tabId = 730410078;
const inspection = await browserjs(tabId, () => {
  // Let's inspect the NY element in the SVG or map
  const allNY = Array.from(document.querySelectorAll('*')).filter(el => el.textContent === 'NY');

  // Let's inspect date controls
  const dateControls = Array.from(document.querySelectorAll('.date-start, .date-end, [formcontrolname*="date" i]')).map(el => ({
    tagName: el.tagName,
    className: el.className,
    value: el.value,
    formControlName: el.getAttribute('formcontrolname')
  }));

  // Let's inspect state controls
  const stateControls = Array.from(document.querySelectorAll('[formcontrolname*="state" i], [placeholder*="state" i]')).map(el => ({
    tagName: el.tagName,
    className: el.className,
    value: el.value,
    formControlName: el.getAttribute('formcontrolname'),
    id: el.id
  }));

  return {
    nyElements: allNY.map(el => ({
      tagName: el.tagName,
      className: el.className,
      id: el.id,
      parentTag: el.parentElement.tagName,
      parentClass: el.parentElement.className
    })),
    dateControls,
    stateControls
  };
});
console.log(JSON.stringify(inspection, null, 2));

