const stateDetails = await browserjs(tabId, () => {
  const comp = document.querySelector('state-select') || document.querySelector('app-root');
  // Look for any badges or pills or selected items
  const pills = Array.from(document.querySelectorAll('.badge, .pill, .tag, .chip, .selected, .state-name, .active')).map(el => ({
    tag: el.tagName,
    class: el.className,
    text: el.textContent.trim()
