const tabId = 730410078;
const eventsData = await browserjs(tabId, () => {
  const monthItems = Array.from(document.querySelectorAll('.month-results'));
  const allEvents = [];

  monthItems.forEach(mItem => {
    const monthHeader = mItem.querySelector('.month-name') || mItem.querySelector('h2, h3, h4, p, div');
    const monthText = mItem.innerText.split('\n')[0].trim();

    // Check if it's September 2026 or October 2026
    if (!/2026/i.test(monthText)) return;
    if (!/SEPTEMBER|OCTOBER/i.test(monthText)) return;

    // Find all event containers in this month
    // Events usually have .event-card or individual event blocks
    const eventBlocks = Array.from(mItem.querySelectorAll('li.event-item, li.day-results, li, div.event-details, div.event-info'));

    // Let's also look at the inner text of this month section to parse events
    allEvents.push({
      month: monthText,
      fullText: mItem.innerText
    });
  });

  return allEvents;
});

console.log("Found months:", eventsData.map(e => e.month));
for (const m of eventsData) {
  console.log("=== " + m.month + " ===");
  console.log(m.fullText);
}

